#!/bin/sh

# cleanup
rm -f counter_step.vcd
rm -rf obj_dir

# run Verilator to translate Verilog into C++, including C++ testbench
verilator -Wall --cc --trace counter_step.sv --exe counter_tb_step.cpp

# build C++ project via make automatically generated by Verilator
make -j -C obj_dir/ -f Vcounter_step.mk Vcounter_step

# run executable simulation file
obj_dir/Vcounter_step